 "content": "from collections import deque

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 5 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 5 and (ny,nx) not in seen:
                        seen.add((ny,nx)); q.append((ny,nx))
            top, bottom = min(y for y,x in comp), max(y for y,x in comp)
            left, right = min(x for y,x in comp), max(x for y,x in comp)
            # Fill the hollow interior of the outlined shape.
            for y in range(top+1, bottom):
                for x in range(left+1, right):
                    if grid[y][x] == 0:
                        out[y][x] = 2
            # Its top edge has a one-cell opening; extend outward in the direction
            # of the longer top-edge segment on either side of that opening.
            gaps = [x for x in range(left, right+1) if grid[top][x] != 5]
            if top > 0 and len(gaps) == 1:
                x = gaps[0]
                left_len, right_len = x-left, right-x
                if left_len >= right_len:
                    for xx in range(0, x+1):
                        if grid[top-1][xx] == 0: out[top-1][xx] = 2
                else:
                    for xx in range(x, w):
                        if grid[top-1][xx] == 0: out[top-1][xx] = 2
    return out
